def write(relative: str, content: str) -> None:
    path = ROOT / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def replace_once(relative: str, before: str, after: str) -> None:
    path = ROOT / relative
    content = path.read_text(encoding="utf-8")
    if before not in content:
        raise SystemExit(f"expected fragment not found in {relative}: {before[:120]!r}")
    path.write_text(content.replace(before, after, 1), encoding="utf-8")


for relative, content in FILES.items():
    write(relative, content)
for relative, before, after in REPLACEMENTS:
    replace_once(relative, before, after)

codeowners = ROOT / ".github/CODEOWNERS"
content = codeowners.read_text(encoding="utf-8")
if "/scripts/check_increment116.py" not in content:
    codeowners.write_text(content.rstrip() + "\n" + OWNER_LINES, encoding="utf-8")

surface_path = ROOT / "docs/roadmap/register-factory-v0.1-surface.json"
surface = json.loads(surface_path.read_text(encoding="utf-8"))
surface["status"] = "api-frozen-implementation-deferred"
implementation = surface["implementation_status"]
implementation["public_api_frozen"] = True
implementation["scala_dsl_implemented"] = True
implementation["surface_compiles"] = True
implementation["scala_type_negative_fixtures_execute"] = True
implementation["semantic_negative_fixtures_are_contract_only"] = True
